 * `status`. No id, priority, or `activeForm` — the list is replaced wholesale
 * on every write (last-write-wins), so entries need no stable identity. The
 * three statuses describe the complete portable lifecycle needed by model and
 * UI consumers.
 */
export interface TodoItem {
    /** What this task is — a short imperative line shown in the UI. */
    content: string;
    /** Lifecycle state. `in_progress` marks a task being worked now; parallel work may mark several. */
    status: 'pending' | 'in_progress' | 'completed';
}
/**
 * Logged request state outside derived history: call config, system prompt, and
 * tools. The latest full `request/header` snapshot reconstructs it; canonical
 * empty optional fields are absent.
 */
export interface EpochHeader {
    /** The conversation's call configuration (provider, model, reasoning effort, and sampling scalars). */
    config: LlmCallConfig;
    /** Effective config fields materialized from the exact adapter rather than proposed by a caller. */
    adapterDefaults?: LlmCallConfigAdapterDefaults;
    /** Rendered system prompt text; absent for a system-less request. */
    system?: string;
    /** Assembled tool schemas; absent for a tool-less request. */
    tools?: ToolSchema[];
}
/** Registration-bound metadata for one resolved model route. */
export interface RequestContext {
    /** Registered provider route the metadata belongs to. */
    provider: string;
    /** Provider-owned model id the metadata belongs to. */
    model: string;
    /** Maximum combined request and response context in tokens, when advertised. */
    contextWindow?: number;
}
/**
 * Why a `request/header` snapshot was appended: `'initial'` — the log's first
 * header (a new conversation); `'resume'` — a loop instance's first request
 * over a log that already has header events (process restart, fork seed);
 * `'change'` — a later request used a different header.
 */
export type RequestHeaderReason = 'initial' | 'resume' | 'change';
/**
 * The merge-extensible, append-only source of truth for an agent interaction.
 * Message history is derived from this log. Every event is lossless JSON and
 * sequence numbers stay contiguous, including raw chunks, so persistence can
 * store the canonical log verbatim.
 */
export interface SessionEventMap {
    /**
     * Opens turn `turn` before the loop claims queued input or runs pre-step.
     * Rejection, empty input, cancellation, or failure may close it with no
     * step; otherwise the following identified `user/message` event or batch
     * records the messages entering the step.
     */
    'turn/start': {
        turn: number;
    };
    /**
     * Closes turn `turn` with the {@link TurnEndReason} that ended it. A turn
     * with no entered step has no `step/start` or `step/end`. The loop does not await a
     * flush at turn boundaries: `dsh-session-checkpoint-policy` owns the
     * per-request durability checkpoint, and consumers that read storage after
     * `whenIdle()` flush themselves. Success commits the turn; rejection is
     * reported live and does not prevent later work.
     */
    'turn/end': {
        turn: number;
        reason: TurnEndReason;
    };
    /** Opens step `step` of turn `turn` — one model call plus the tool executions it requested. */
    'step/start': {
        turn: number;
        step: number;
    };
    /** Closes step `step` of turn `turn`. */
    'step/end': {
        turn: number;
        step: number;
    };
    /**
     * A user-role message on the model-visible surface: a direct human prompt
     * (the queued message claimed for this turn), a synthetic `agent.inject()`
     * context (file-change notices, subdir AGENTS.md, skill content, cron
     * notifications, …), or an entered goal continuation round. All three
     * project their `content` verbatim; `source` tells them apart.
     */
    'user/message': UserMessage;
    /** Raw stream chunk — token-level replay fidelity. */
    'assistant/chunk': {
        turn: number;
        step: number;
        chunk: StreamChunk;
    };
    /**
     * Assembled assistant message for one step (derived history uses this).
     * Carries the step's `usage` when the adapter reported token accounting, so
     * the model output and its accounting travel together (there is no separate
     * usage record). `usage` is absent when the adapter reported none.
     */
    'assistant/message': {
        turn: number;
        step: number;
        message: AssistantMessage;
        usage?: TokenUsage;
    };
    /**
     * The model requested one tool invocation: `name` with the raw `arguments`
     * JSON string exactly as the model produced it (unparsed). `callId` pairs the
     * call with its `tool/result`.
     */
    'tool/call': {
        turn: number;
        step: number;
        callId: CallId;
        name: string;
        arguments: string;
    };
    /**
     * A completed tool call's model-facing result, optional internal failure
     * identity, and optional tool-private `meta` presentation payload. `meta` is
     * opaque to the core (the producing tool owns its shape and reads it back in
     * `presentResult`) but MUST be JSON-serializable: `Session.append`
     * runtime-validates all event data with `isJsonValue`, so a non-serializable
     * `meta` is rejected at the source, and the durable log reproduces the
     * identical card on replay. Absent
     * unless the tool attaches one (e.g. `dsh-tool-fs` carries its result-time
     * contextual diff here).
     */
    'tool/result': {
        turn: number;
        step: number;
        message: ToolResultMessage;
        error?: {
            name: string;
            code: string;
        };
        meta?: JsonValue;
    };
    /** Whole-list snapshot; latest write wins on replay. Log-only UI state; never derived history. */
    'todo/write': {
        todos: TodoItem[];
    };
    /**
     * Full header for the next request, appended inside its step before dispatch.
     * It is log-only; the latest snapshot reconstructs the request header.
     */
    'request/header': {
        header: EpochHeader;
        reason: RequestHeaderReason;
    };
    /**
     * Route metadata for the next request, logged only when the route or capacity
     * changes. It does not participate in request reconstruction or header equality.
     */
    'request/context': RequestContext;
    /**
     * Marks the end of a constructor seed. Events before it have smaller seq
     * values and came from the seed (resume, fork, or replay); this lifecycle
     * produced none of them. This log-only event is the durable projection of
     * {@link Session.firstLiveSeq}. Its payload is empty — position and `time`
     * carry the meaning.
     *
     * Locate the LAST one in stored history. A seed already ending in one is not
     * re-marked, so reopening an untouched session does not grow its log per
     * pickup and the event need not be at the current `firstLiveSeq`.
     *
     * `Session`'s constructor is the only legitimate writer. The invariant
     * companion deliberately constrains nothing here, so a plugin appending one
     * would silently classify every live bracket before it as seed history.
     *
     * An owner of a standalone open/close bracket (`compaction/start` …
     * `compaction/end`) reads it because seed history and live work are otherwise
     * byte-identical: an unmatched opening marker before this event belongs to
     * an ended lifecycle, whatever ended it. NOT a liveness signal about other
     * writers — a concurrently live session holds its own boundary elsewhere,
     * so tolerating concurrent writers needs a signal beyond the log.
     */
    'session/end-seed': Record<string, never>;
}
/** The appendable event-type keys of {@link SessionEventMap}, plugin-merged extensions included. */
export type SessionEventType = keyof SessionEventMap;
/**
 * The subset of {@link SessionEventType} values whose events produce LLM
 * messages and are eligible to appear on the ordered surface. Only these
 * event types may carry {@link SurfaceOp} and {@link SessionEvent.sourceEventSeqs}.
 */
export type SurfaceEventType = 'user/message' | 'assistant/message' | 'tool/result';
/**
 * A {@link SessionEvent} that is **on** the ordered surface — its
 * `surfaceOp` is guaranteed present (mandatory), narrowed from a
 * surface-eligible {@link SessionEvent} by checking both `type` and
 * `surfaceOp` at runtime.
 *
 * Use the `isSurfaceEvent` type guard (in `surface.ts`) to narrow a
 * `SessionEvent` to this type.
 */
export type SurfaceEvent = SessionEvent<SurfaceEventType> & {
    surfaceOp: SurfaceOp;
};
/**
 * How a session event entered the ordered surface. Only valid on
 * {@link SurfaceEventType} events.
 *
 * - `'append'`: added to the tail — normal path for user/assistant/tool
 *   messages.
 * - `{ op: 'replace', start, end }`: replaces surface nodes from `start`
 *   (inclusive) through `end` (inclusive) with this node. Both must exist as
 *   surface nodes in the current surface. `start === end` replaces a single
 *   node. The node's {@link SessionEvent.sourceEventSeqs} must include every
 *   shadowed surface node. Used by compaction; any surface-replacing producer
 *   may use it.
 */
export type SurfaceOp = 'append' | {
    op: 'replace';
    start: number;
    end: number;
};
/**
 * Surface placement and cited source-event seqs for {@link Session.append}. Required on
 * message-producing events and forbidden on log-only events.
 */
export interface SurfaceIntent {
    surfaceOp: SurfaceOp;
    /**
     * Complete set of known source-event seqs. `assistant/message` may use a
     * present empty array for a known empty provider stream; when the field is
     * absent, the event does not record which earlier events produced the message.
     * Other surface events require a non-empty set when this field is present.
     */
    sourceEventSeqs?: number[];
}
/**
 * One immutable entry in the session log.
 *
 * A proper discriminated union over `type` (not independent `type`/`data`
 * unions), so `switch (event.type)` narrows `event.data` without casts.
 *
 * The {@link sourceEventSeqs} and {@link surfaceOp} fields are conditional:
 * they only exist on {@link SurfaceEventType} variants (`user/message`,
 * `assistant/message`, `tool/result`).
 * Non-surface events (boundary markers, chunks, usage, errors) never carry
 * surface metadata — the compiler enforces this at `Session.append()`
 * call sites.
 */
export type SessionEvent<T extends SessionEventType = SessionEventType> = {
    [K in SessionEventType]: {
        type: K;
        /** Monotonic sequence number within the session. */
        seq: number;
        /** Unix epoch milliseconds. */
        time: number;
        data: SessionEventMap[K];
        /**
         * Marks an event a reader may safely skip when it does not recognize
         * `type`. Absent means required: a reader meeting an unrecognized type
         * without this marker MUST refuse to reconstruct the session instead of
         * silently dropping the event, because an unrecognized required event may
         * change how the rest of the log is interpreted. A writer sets `true` only
         * on purely informational records whose loss cannot affect reconstruction;
         * defaulting to required means a forgotten marker over-refuses (an
         * inconvenience) rather than silently resuming a gutted session.
         */
        ignorable?: true;
    } & (K extends SurfaceEventType ? {
        /**
         * Seq numbers of earlier events that this event cites as sources
         * (e.g. the `assistant/chunk` seqs that built an `assistant/message`,
         * or the surface nodes shadowed by a compaction replace node). An
         * `assistant/message` may carry a present empty array for a known empty
         * provider stream; when the field is absent, the event does not record which
         * earlier events produced the message.
         */
        sourceEventSeqs?: number[];
        /** How this event entered the surface; absent for non-surface events. */
        surfaceOp?: SurfaceOp;
    } : object);
}[T];

/**
 * Tool render-intent vocabulary: the provider-neutral types a tool declares via
 * `ToolDefinition.presentCall`/`ToolDefinition.presentResult` to say how one of its calls
 * renders in a UI (an editor's tool-call card, a CLI log line).
 * @module @deepseek-ai/dsh-tools/src/presentation
 */
import type { ContentBlock } from '@deepseek-ai/dsh-llm';
